"""LangChain Embeddings adapter backed by the Transformers.js microservice.

LangChain expects a synchronous ``Embeddings`` interface, so this adapter uses a
blocking HTTP client to reach the Node.js embeddings service exclusively.
"""

import logging
from typing import List

import httpx
from langchain_core.embeddings import Embeddings

from app.core.exceptions import EmbeddingsServiceError
from app.config import Settings

logger = logging.getLogger("app")


class TransformersJsEmbeddings(Embeddings):
    """LangChain-compatible embeddings generated by Transformers.js over HTTP."""

    def __init__(self, settings: Settings) -> None:
        self.base_url = settings.EMBEDDINGS_SERVICE_URL.rstrip("/")
        self.model = settings.EMBEDDINGS_MODEL

    def _embed(self, texts: List[str]) -> List[List[float]]:
        if not texts:
            return []
        try:
            with httpx.Client(timeout=120.0) as client:
                response = client.post(
                    f"{self.base_url}/embed",
                    json={"texts": texts, "model": self.model},
                )
                response.raise_for_status()
                return response.json()["embeddings"]
        except httpx.HTTPError as exc:
            logger.error("Embeddings service request failed: %s", exc)
            raise EmbeddingsServiceError(str(exc))

    def embed_documents(self, texts: List[str]) -> List[List[float]]:
        return self._embed(texts)

    def embed_query(self, text: str) -> List[float]:
        return self._embed([text])[0]
